#!/usr/bin/env bash
set -euo pipefail

# =============================================================================
# FACTS Sea Level Experiment Runner - Apptainer
# Generated by facts-experiment-builder
# =============================================================================

# --- Paths -------------------------------------------------------------------
WORKSPACE="/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2"
DATA_DIR="${WORKSPACE}/data"
EXPERIMENT_NAME="apptainer_experiments/bam_ssp585_fixed"
OUTPUT_DIR="/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/bam_ssp585_fixed/output-apptainer"
SHARED_IN="/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/data/shared_input_data"
MODULE_IN="/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/data/module_specific_input_data"
SIF_DIR="/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/sif"

# --- Global params -----------------------------------------------------------
PYEAR_START=2020
PYEAR_END=2150
PYEAR_STEP=10
BASEYEAR=2005
SCENARIO="ssp585"
NSAMPS=500
PIPELINE_ID="bam001"
WORKFLOW1_NAME="all-modules"

# --- Helpers -----------------------------------------------------------------

log() { echo "[$(date '+%H:%M:%S')] $*"; }

pull_image() {
    local name="$1"
    local ref="$2"
    local sif="${SIF_DIR}/${name}.sif"
    if [[ ! -f "$sif" ]]; then
        log "Pulling ${ref} -> ${sif}"
        apptainer pull --disable-cache "$sif" "docker://${ref}"
    else
        log "Image already exists: ${sif}"
    fi
}

# Per-service --env flags; set before a service that needs them and reset after.
ENV_ARGS=()

run_service() {
    local name="$1"
    local sif="${SIF_DIR}/${name}.sif"
    shift
    log "Running service: ${name}"
    # --pwd /: the home dir is hidden by --containall/--no-home, so don't start there.
    # ${ENV_ARGS[@]+...}: expands to nothing for an empty array under `set -u`.
    apptainer run \
        --no-home \
        --containall \
        --pwd / \
        "${BINDS[@]}" \
        ${ENV_ARGS[@]+"${ENV_ARGS[@]}"} \
        "$sif" \
        "$@"
    log "Completed: ${name}"
}

wait_for_output() {
    # Poll until an expected output file exists (used to gate stage 2)
    local file="$1"
    local service="$2"
    log "Waiting for output of ${service}: ${file}"
    local attempts=0
    until [[ -f "$file" ]]; do
        sleep 5
        attempts=$((attempts + 1))
        if (( attempts > 360 )); then   # 30-minute timeout
            echo "ERROR: Timed out waiting for ${file}" >&2
            exit 1
        fi
    done
    log "Output ready: ${file}"
}

# --- Setup -------------------------------------------------------------------
mkdir -p \
    "${SIF_DIR}" \
    "/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/bam_ssp585_fixed/output-apptainer/fair-temperature" \
    "/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/bam_ssp585_fixed/output-apptainer/bamber19-icesheets" \
    "/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/bam_ssp585_fixed/output-apptainer/facts-total"

# --- Pull images -------------------------------------------------------------
log "=== Pulling images ==="
pull_image "fair-temperature-0.2.1" "ghcr.io/fact-sealevel/fair-temperature:0.2.1"
pull_image "bamber19-icesheets-0.2.0" "ghcr.io/fact-sealevel/bamber19-icesheets:0.2.0"
pull_image "facts-total-all-modules-global-0.2.1" "ghcr.io/fact-sealevel/facts-total:0.2.1"
pull_image "facts-total-all-modules-local-0.2.1" "ghcr.io/fact-sealevel/facts-total:0.2.1"

# =============================================================================
# Stage 1: Climate module + non-climate-dependent sealevel modules
# =============================================================================
log "=== Stage 1: independent services ==="

# --- fair-temperature ---
BINDS=(
    "--bind=/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/data/module_specific_input_data/fair-temperature:/mnt/module_specific_in"
    "--bind=/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/data/shared_input_data:/mnt/shared_in"
    "--bind=/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/bam_ssp585_fixed/output-apptainer:/mnt/out"
)
run_service "fair-temperature-0.2.1" \
    "--pipeline-id=bam001" \
    "--nsamps=500" \
    "--scenario=ssp585" \
    "--cyear-start=1850" \
    "--cyear-end=1900" \
    "--smooth-win=19" \
    "--seed=2314" \
    "--rcmip-file=/mnt/module_specific_in/rcmip/rcmip-emissions-annual-means-v5-1-0.csv" \
    "--param-file=/mnt/module_specific_in/parameters/fair_ar6_climate_params_v4.0.nc" \
    "--output-oceantemp-file=/mnt/out/fair-temperature/oceantemp.nc" \
    "--output-climate-file=/mnt/out/fair-temperature/climate.nc" \
    "--output-ohc-file=/mnt/out/fair-temperature/ohc.nc" \
    "--output-gsat-file=/mnt/out/fair-temperature/gsat.nc"

# =============================================================================
# Stage 2: Sealevel modules depending on climate output
# =============================================================================
log "=== Stage 2: services depending on climate step ==="
wait_for_output "/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/bam_ssp585_fixed/output-apptainer/fair-temperature/climate.nc" "fair-temperature"

# --- bamber19-icesheets ---
BINDS=(
    "--bind=/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/data/module_specific_input_data/bamber19-icesheets:/mnt/module_specific_in"
    "--bind=/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/data/shared_input_data:/mnt/shared_in"
    "--bind=/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/bam_ssp585_fixed/output-apptainer:/mnt/out"
)
run_service "bamber19-icesheets-0.2.0" \
    "--pipeline-id=bam001" \
    "--nsamps=500" \
    "--scenario=ssp585" \
    "--pyear-start=2020" \
    "--pyear-end=2150" \
    "--pyear-step=10" \
    "--baseyear=2005" \
    "--location-file=/mnt/shared_in/location.lst" \
    "--fingerprint-dir=/mnt/shared_in/FPRINT" \
    "--replace=1" \
    "--chunksize=50" \
    "--rngseed=1423" \
    "--climate-data-file=/mnt/out/fair-temperature/climate.nc" \
    "--slr-proj-mat-file=/mnt/module_specific_in/SLRProjections190726core_SEJ_full.mat" \
    "--output-AIS-gslr-file=/mnt/out/bamber19-icesheets/AIS-gslr.nc" \
    "--output-EAIS-gslr-file=/mnt/out/bamber19-icesheets/EAIS-gslr.nc" \
    "--output-WAIS-gslr-file=/mnt/out/bamber19-icesheets/WAIS-gslr.nc" \
    "--output-GIS-gslr-file=/mnt/out/bamber19-icesheets/GIS-gslr.nc" \
    "--output-AIS-lslr-file=/mnt/out/bamber19-icesheets/AIS-lslr.nc" \
    "--output-EAIS-lslr-file=/mnt/out/bamber19-icesheets/EAIS-lslr.nc" \
    "--output-WAIS-lslr-file=/mnt/out/bamber19-icesheets/WAIS-lslr.nc" \
    "--output-GIS-lslr-file=/mnt/out/bamber19-icesheets/GIS-lslr.nc"

# =============================================================================
# Stage 3: Totaling step (parallel, one per workflow × output type)
# =============================================================================
log "=== Stage 3: facts-total ==="

BINDS=(
    "--bind=/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/data/shared_input_data:/mnt/shared_in"
    "--bind=/panfs/ccds02/nobackup/projects/ilab/projects/sealevel/facts2/apptainer_experiments/bam_ssp585_fixed/output-apptainer:/mnt/total_out"
)
run_service "facts-total-all-modules-global-0.2.1" \
    "--pyear-start=2020" \
    "--pyear-end=2150" \
    "--pyear-step=10" \
    "--item=/mnt/total_out/bamber19-icesheets/AIS-gslr.nc" \
    "--item=/mnt/total_out/bamber19-icesheets/GIS-gslr.nc" \
    "--output-path=/mnt/total_out/facts-total/all-modules_global_total.nc" &
PID_FACTS_TOTAL_ALL_MODULES_GLOBAL=$!

run_service "facts-total-all-modules-local-0.2.1" \
    "--pyear-start=2020" \
    "--pyear-end=2150" \
    "--pyear-step=10" \
    "--item=/mnt/total_out/bamber19-icesheets/AIS-lslr.nc" \
    "--item=/mnt/total_out/bamber19-icesheets/GIS-lslr.nc" \
    "--output-path=/mnt/total_out/facts-total/all-modules_local_total.nc" &
PID_FACTS_TOTAL_ALL_MODULES_LOCAL=$!

wait $PID_FACTS_TOTAL_ALL_MODULES_GLOBAL || { echo "ERROR: facts-total-all-modules-global failed" >&2; exit 1; }
wait $PID_FACTS_TOTAL_ALL_MODULES_LOCAL || { echo "ERROR: facts-total-all-modules-local failed" >&2; exit 1; }

log "Experiment complete."
